(function attachVM(globalThis) {
  /**
   * The simple random walk on an undirected graph: from a vertex, move to
   * a uniformly chosen neighbor, so `P[i][j] = 1 / deg(i)` for each edge.
   * Its stationary distribution is proportional to degree,
   * `pi_i = deg(i) / (2 * |E|)`, which is returned alongside.
   *
   * The lazy walk stays put with probability 1/2 and otherwise takes a
   * simple-walk step, `(I + P) / 2`. It has the same stationary
   * distribution but no eigenvalue at `-1`, so it converges on a bipartite
   * graph (a path, a tree, a grid, an even cycle), where the simple walk
   * oscillates forever.
   *
   * @param {number} nodeCount - Vertices are `0..nodeCount-1`.
   * @param {Array<[number, number]>} edges - Undirected edges; each listed
   *   once. Self-loops and repeated edges are not checked for.
   * @param {Object} [opts]
   * @param {boolean} [opts.lazy=false] - Return the lazy walk.
   * @returns {{P: number[][], degrees: number[], stationary: number[]}}
   *   `P` is row-stochastic. An isolated vertex (degree 0) gets a row that
   *   stays put, `P[i][i] = 1`, and stationary mass 0; with no edges at all
   *   `stationary` is uniform.
   */
  const randomWalkMatrix = (nodeCount, edges, opts = {}) => {
    const lazy = opts.lazy ?? false
    const degrees = new Array(nodeCount).fill(0)
    for (const [u, v] of edges) {
      degrees[u]++
      degrees[v]++
    }

    const P = []
    for (let i = 0; i < nodeCount; i++) P.push(new Array(nodeCount).fill(0))
    for (const [u, v] of edges) {
      P[u][v] += 1 / degrees[u]
      P[v][u] += 1 / degrees[v]
    }
    for (let i = 0; i < nodeCount; i++) {
      if (degrees[i] === 0) P[i][i] = 1
    }
    if (lazy) {
      for (let i = 0; i < nodeCount; i++) {
        for (let j = 0; j < nodeCount; j++) P[i][j] /= 2
        P[i][i] += 0.5
      }
    }

    let totalDegree = 0
    for (const d of degrees) totalDegree += d
    const stationary = []
    for (let i = 0; i < nodeCount; i++) {
      if (totalDegree === 0) {
        stationary.push(1 / nodeCount)
      } else {
        stationary.push(degrees[i] / totalDegree)
      }
    }

    return {P, degrees, stationary}
  }

  globalThis.VM = {...globalThis.VM, discreteMath: {...globalThis.VM?.discreteMath, randomWalkMatrix}}
})(window)

// ---- src/js/discrete-math/spring-layout.js ----
;
/**
 * Copyright (c) 2026 Apurva Nakade. All rights reserved.
 * Released under Apache 2.0 license as described in the file LICENSE.
 * Authors: Apurva Nakade
 */

(function attachVM(globalThis) {
  /**
   * Force-directed (Fruchterman-Reingold) layout of an undirected graph:
   * every pair of vertices repels with force `k^2 / d`, every edge pulls
   * its ends together with force `d^2 / k`, and each vertex moves along its
   * net force by at most a "temperature" that cools linearly to zero. Dense
   * clusters end up as tight blobs and a bottleneck edge as a long bridge
   * between them, which is what makes the picture worth drawing.
   *
   * Deterministic: the starting positions come from
   * `VM.sampling.seededRandom(seed)`, so the same graph and seed always give
   * the same picture.
   *
   * @param {number} nodeCount - Vertices are `0..nodeCount-1`.
   * @param {Array<[number, number]>} edges - Undirected edges.
   * @param {Object} [opts]
   * @param {number} [opts.seed=42] - Seed for the starting positions.
   * @param {number} [opts.iterations=300]
   * @returns {Array<[number, number]>} One `[x, y]` per vertex, centered
   *   on the origin and scaled so the larger coordinate extent is
   *   `[-1, 1]`. A single vertex sits at `[0, 0]`; `[]` for no vertices.
   */
  const springLayout = (nodeCount, edges, opts = {}) => {
    const seed = opts.seed ?? 42
    const iterations = opts.iterations ?? 300
    if (nodeCount === 0) return []
    if (nodeCount === 1) return [[0, 0]]

    const rng = globalThis.VM.sampling.seededRandom(seed)
    const xs = []
    const ys = []
    for (let i = 0; i < nodeCount; i++) {
      xs.push(rng())
      ys.push(rng())
    }

    const k = Math.sqrt(1 / nodeCount)
    const startTemperature = 0.1
    for (let iter = 0; iter < iterations; iter++) {
      const temperature = startTemperature * (1 - iter / iterations)
      const dx = new Array(nodeCount).fill(0)
      const dy = new Array(nodeCount).fill(0)

      for (let i = 0; i < nodeCount; i++) {
        for (let j = i + 1; j < nodeCount; j++) {
          const ex = xs[i] - xs[j]
          const ey = ys[i] - ys[j]
          const dist = Math.max(Math.hypot(ex, ey), 1e-3)
          const force = (k * k) / dist
          dx[i] += (ex / dist) * force
          dy[i] += (ey / dist) * force
          dx[j] -= (ex / dist) * force
          dy[j] -= (ey / dist) * force
        }
      }

      for (const [u, v] of edges) {
        const ex = xs[u] - xs[v]
        const ey = ys[u] - ys[v]
        const dist = Math.max(Math.hypot(ex, ey), 1e-3)
        const force = (dist * dist) / k
        dx[u] -= (ex / dist) * force
        dy[u] -= (ey / dist) * force
        dx[v] += (ex / dist) * force
        dy[v] += (ey / dist) * force
      }

      for (let i = 0; i < nodeCount; i++) {
        const length = Math.hypot(dx[i], dy[i])
        if (length === 0) continue
        const step = Math.min(length, temperature)
        xs[i] += (dx[i] / length) * step
        ys[i] += (dy[i] / length) * step
      }
    }

    let xMin = Infinity, xMax = -Infinity, yMin = Infinity, yMax = -Infinity
    for (let i = 0; i < nodeCount; i++) {
      xMin = Math.min(xMin, xs[i])
      xMax = Math.max(xMax, xs[i])
      yMin = Math.min(yMin, ys[i])
      yMax = Math.max(yMax, ys[i])
    }
    const cx = (xMin + xMax) / 2
    const cy = (yMin + yMax) / 2
    let half = Math.max(xMax - xMin, yMax - yMin) / 2
    if (half === 0) half = 1

    const out = []
    for (let i = 0; i < nodeCount; i++) out.push([(xs[i] - cx) / half, (ys[i] - cy) / half])
    return out
  }

  globalThis.VM = {...globalThis.VM, discreteMath: {...globalThis.VM?.discreteMath, springLayout}}
})(window)

// ---- src/js/numerical/symmetric-eigenvalues.js ----
;
/**
 * Copyright (c) 2026 Apurva Nakade. All rights reserved.
 * Released under Apache 2.0 license as described in the file LICENSE.
 * Authors: Apurva Nakade
 */

(function attachVM(globalThis) {
  /**
   * Eigenvalues of a real symmetric matrix by the cyclic Jacobi method:
   * sweep over every off-diagonal entry, zeroing each with a plane
   * rotation, until the off-diagonal part is negligible. Slow (`O(k^3)` per
   * sweep) but short, dependency-free and accurate for the few-dozen-row
   * matrices a page draws, e.g. the symmetrized transition matrix
   * `D^{1/2} P D^{-1/2}` of a random walk, whose eigenvalues are `P`'s.
   *
   * @param {number[][]} A - Symmetric `k x k` matrix. Only symmetry of the
   *   input is assumed, not checked; `A` itself is not modified.
   * @param {Object} [opts]
   * @param {number} [opts.tolerance=1e-12] - Stop once the off-diagonal
   *   sum of squares falls below this.
   * @param {number} [opts.maxSweeps=100]
   * @returns {number[]} The `k` eigenvalues, sorted descending (with
   *   multiplicity). `[]` for an empty matrix.
   */
  const symmetricEigenvalues = (A, opts = {}) => {
    const tolerance = opts.tolerance ?? 1e-12
    const maxSweeps = opts.maxSweeps ?? 100
    const k = A.length
    const a = []
    for (const row of A) a.push(row.slice())

    for (let sweep = 0; sweep < maxSweeps; sweep++) {
      let off = 0
      for (let i = 0; i < k; i++) {
        for (let j = i + 1; j < k; j++) off += a[i][j] * a[i][j]
      }
      if (off < tolerance) break

      for (let p = 0; p < k; p++) {
        for (let q = p + 1; q < k; q++) {
          if (Math.abs(a[p][q]) < 1e-300) continue
          // The rotation angle that zeroes a[p][q]; t = tan(theta), taken
          // as the smaller root for stability.
          const theta = (a[q][q] - a[p][p]) / (2 * a[p][q])
          let t = 1 / (Math.abs(theta) + Math.sqrt(theta * theta + 1))
          if (theta < 0) t = -t
          const c = 1 / Math.sqrt(t * t + 1)
          const s = t * c

          for (let r = 0; r < k; r++) {
            const arp = a[r][p]
            const arq = a[r][q]
            a[r][p] = c * arp - s * arq
            a[r][q] = s * arp + c * arq
          }
          for (let r = 0; r < k; r++) {
            const apr = a[p][r]
            const aqr = a[q][r]
            a[p][r] = c * apr - s * aqr
            a[q][r] = s * apr + c * aqr
          }
        }
      }
    }

    const values = []
    for (let i = 0; i < k; i++) values.push(a[i][i])
    values.sort((x, y) => y - x)
    return values
  }

  globalThis.VM = {...globalThis.VM, numerical: {...globalThis.VM?.numerical, symmetricEigenvalues}}
})(window)

